   330  protected int
   331  file_reset(struct magic_set *ms)
   332  {
   333          if (ms->mlist[0] == NULL) {
   334                  file_error(ms, 0, "no magic files loaded");
   335                  return -1;
   336          }
   337          if (ms->o.buf) {
   338                  free(ms->o.buf);
   339                  ms->o.buf = NULL;
   340          }
   341          if (ms->o.pbuf) {
   342                  free(ms->o.pbuf);
   343                  ms->o.pbuf = NULL;
   344          }
   345          ms->event_flags &= ~EVENT_HAD_ERR;
   346          ms->error = -1;
   347          return 0;
