   350  #define OCTALIFY(n, o)  \
   351          /*LINTED*/ \
   352          (void)(*(n)++ = '\\', \
   353          *(n)++ = (((uint32_t)*(o) >> 6) & 3) + '0', \
   354          *(n)++ = (((uint32_t)*(o) >> 3) & 7) + '0', \
   355          *(n)++ = (((uint32_t)*(o) >> 0) & 7) + '0', \
   356          (o)++)
