   855  private uint32_t
   856  cvt_id3(struct magic_set *ms, uint32_t v)
   857  {
   858          v = ((((v >>  0) & 0x7f) <<  0) |
   859               (((v >>  8) & 0x7f) <<  7) |
   860               (((v >> 16) & 0x7f) << 14) |
   861               (((v >> 24) & 0x7f) << 21));
   862          if ((ms->flags & MAGIC_DEBUG) != 0)
   863                  fprintf(stderr, "id3 offs=%u\n", v);
   864          return v;
   865  }
