  1300  private uint32_t
  1301  do_ops(struct magic *m, intmax_t lhs, intmax_t off)
  1302  {
  1303          intmax_t offset;
  1304          if (off) {
  1305                  switch (m->in_op & FILE_OPS_MASK) {
  1306                  case FILE_OPAND:
  1307                          offset = lhs & off;
  1308                          break;
  1309                  case FILE_OPOR:
  1310                          offset = lhs | off;
  1311                          break;
  1312                  case FILE_OPXOR:
  1313                          offset = lhs ^ off;
  1314                          break;
  1315                  case FILE_OPADD:
  1316                          offset = lhs + off;
  1317                          break;
  1318                  case FILE_OPMINUS:
  1319                          offset = lhs - off;
  1320                          break;
  1321                  case FILE_OPMULTIPLY:
  1322                          offset = lhs * off;
  1323                          break;
  1324                  case FILE_OPDIVIDE:
  1325                          offset = lhs / off;
  1326                          break;
  1327                  case FILE_OPMODULO:
  1328                          offset = lhs % off;
  1329                          break;
  1330                  }
  1331          } else
  1332                  offset = lhs;
  1333          if (m->in_op & FILE_OPINVERSE)
  1334                  offset = ~offset;
  1335
  1336          return (uint32_t)offset;
  1337  }
