   517  protected void
   518  file_regfree(file_regex_t *rx)
   519  {
   520          if (rx->rc == 0)
   521                  regfree(&rx->rx);
   522  #ifdef USE_C_LOCALE
   523          (void)uselocale(rx->old_lc_ctype);
   524          freelocale(rx->c_lc_ctype);
   525  #else
   526          (void)setlocale(LC_CTYPE, rx->old_lc_ctype);
   527  #endif
   528  }
